#nullable enable // autogenerated

using MVZ2Logic.Definitions;
using MVZ2Logic.Options;

namespace MVZ2Logic.Contents.Options
{
    [AutoOptionWidgetDefinition(LogicOptionWidgetNames.autoUpdateSponsors)]
    public class AutoUpdateSponsorsOptionToggle : OptionToggleDefinition
    {
        public AutoUpdateSponsorsOptionToggle(string nsp, string name) : base(nsp, name)
        {
        }
        public override bool GetValue(IOptionContext context)
        {
            return Global.Options.GetOptionBool(LogicOptionItemID.autoUpdateSponsors);
        }

        public override void OnValueChanged(IOptionContext context, bool value)
        {
            Global.Options.SetOptionBool(LogicOptionItemID.autoUpdateSponsors, value);
            Global.Options.SaveOptions();
        }
    }
}
